def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    Tokens are strings representing integers or the operators +, -, *, /.
    Division truncates toward zero, matching the behaviour of the original
    LeetCode problem.
    """
    stack = []
    for token in tokens:
        # integer literals may be negative
        if token.lstrip('-').isdigit():
            stack.append(int(token))
        else:
            # pop operands in reverse order: b is the right operand
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                # Python's int division truncates toward zero when using // only for positive numbers.
                # Use int(a / b) which truncates toward zero for both signs.
                stack.append(int(a / b))
            else:
                raise ValueError(f"Unsupported operator: {token}")
    # If the expression was empty, return 0 (though problem guarantees at least one token)
    return stack[0] if stack else 0

def solve(s):
    # Handle non-string inputs gracefully
    if not isinstance(s, str) or not s:
        return []
    result = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = ch
            count = 1
    result.append([prev, count])
    return result

