def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each token is an integer or an operator '+', '-', '*', '/'.
    Division truncates toward zero as per problem statement.
    Returns integer result.
    """
    stack = []
    for token in tokens:
        if token in {"+", "-", "*", "/"}:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # Python division // truncates toward negative infinity, need trunc toward zero
                # Use int(a / b) which truncates toward zero for positive and negative
                if b == 0:
                    raise ZeroDivisionError("division by zero")
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

