    Supports integers (including negative) and '+', '-', '*', '/' operators.
    Division truncates toward zero.
    """
    stack = []
    for token in tokens:
        # check if token is an integer (including negative numbers)
        if token.lstrip('-').isdigit():
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                # Truncate toward zero using int division of float
                stack.append(int(a / b))
            else:
                raise ValueError(f"Unsupported operator: {token}")
    return stack[0] if stack else 0

