def solve(a: str, b: str) -> int:
    # DP for Levenshtein distance (insert, delete, replace)
    m, n = len(a), len(b)
    # If one is empty, distance is length of the other
    if m == 0:
        return n
    if n == 0:
        return m
    # Initialize previous row
    prev = list(range(n + 1))
    for i in range(1, m + 1):
        cur = [i] + [0] * n
        ai = a[i - 1]
        for j in range(1, n + 1):
            if ai == b[j - 1]:
                cost = 0
            else:
                cost = 1
            cur[j] = min(
                prev[j] + 1,      # deletion
                cur[j - 1] + 1,   # insertion
                prev[j - 1] + cost  # substitution
            )
        prev = cur
    return prev[n]

